// AWI: diagnosa sementara nama Ti7 (hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/ti7', array(
		'methods' => 'GET',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$re = '#.{0,50}(?<![a-z0-9/_-])ti[ -]?7(?![0-9])(?![a-z]).{0,40}#is';
			$out = array('posts' => array(), 'meta' => array(), 'opts' => array(), 'snip' => array(), 'terms' => array());
			$rows = $wpdb->get_results("SELECT ID, post_type, post_status, post_title, post_excerpt, post_content, post_name FROM {$wpdb->posts} WHERE post_type NOT IN ('revision','customize_changeset','oembed_cache') AND post_status NOT IN ('trash','auto-draft','inherit') AND (post_title REGEXP '[Tt][Ii][ -]?7' OR post_content REGEXP '[Tt][Ii][ -]?7' OR post_excerpt REGEXP '[Tt][Ii][ -]?7')");
			foreach ($rows as $r) {
				$hits = array();
				foreach (array('post_title', 'post_excerpt', 'post_content') as $f) {
					if (preg_match_all($re, wp_strip_all_tags($r->$f), $m)) {
						foreach (array_slice($m[0], 0, 12) as $x) $hits[] = $f . ': ' . trim(preg_replace('/\s+/', ' ', $x));
					}
				}
				if ($hits) $out['posts'][] = array('id' => $r->ID, 'type' => $r->post_type, 'st' => $r->post_status, 'slug' => $r->post_name, 'title' => $r->post_title, 'n' => count($hits), 'hits' => $hits);
			}
			$m2 = $wpdb->get_results("SELECT post_id, meta_key, meta_value FROM {$wpdb->postmeta} WHERE meta_value REGEXP '[Tt][Ii][ -]?7' AND meta_key NOT LIKE '\\_oembed%' LIMIT 200");
			foreach ($m2 as $r) { if (preg_match_all($re, wp_strip_all_tags((string) $r->meta_value), $m)) $out['meta'][] = array($r->post_id, $r->meta_key, array_slice($m[0], 0, 4)); }
			$o2 = $wpdb->get_results("SELECT option_name, option_value FROM {$wpdb->options} WHERE option_value REGEXP '[Tt][Ii][ -]?7' AND option_name NOT LIKE '%transient%' LIMIT 100");
			foreach ($o2 as $r) { if (preg_match_all($re, (string) $r->option_value, $m)) $out['opts'][] = array($r->option_name, count($m[0]), array_slice($m[0], 0, 3)); }
			$s2 = $wpdb->get_results("SELECT id, name, active, code FROM {$wpdb->prefix}snippets WHERE code REGEXP '[Tt][Ii][ -]?7'");
			foreach ($s2 as $r) { if (preg_match_all($re, $r->code, $m)) $out['snip'][] = array($r->id, $r->name, $r->active, count($m[0]), array_slice($m[0], 0, 8)); }
			$t2 = $wpdb->get_results("SELECT t.term_id, t.name, tt.taxonomy, tt.description FROM {$wpdb->terms} t JOIN {$wpdb->term_taxonomy} tt ON tt.term_id=t.term_id WHERE t.name REGEXP '[Tt][Ii][ -]?7' OR tt.description REGEXP '[Tt][Ii][ -]?7'");
			$out['terms'] = $t2;
			return $out;
		},
	));
});
